// Replicates LandmarkCapture.normalizeLandmarks in plain JS to test the MATH.
const sub=(a,b)=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]];
const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const scl=(a,s)=>[a[0]*s,a[1]*s,a[2]*s];
const len=a=>Math.sqrt(dot(a,a));
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const N=26, WRIST=0, INDEX_KNUCKLE=7, MIDDLE_KNUCKLE=12, PINKY_KNUCKLE=22, EPS=1e-4;

function normalize(pts, mirror=false){
  const w=pts[WRIST], mk=pts[MIDDLE_KNUCKLE], ik=pts[INDEX_KNUCKLE], pk=pts[PINKY_KNUCKLE];
  const fwd=sub(mk,w); const scale=len(fwd); if(scale<EPS) return null;
  const inv=1/scale; const y=scl(fwd,inv);
  const spread=sub(pk,ik);
  const perp=sub(spread, scl(y,dot(spread,y)));
  const pl=len(perp); if(pl<EPS) return null;
  const x=scl(perp,1/pl);
  const z=cross(x,y);
  const out=new Float64Array(78);
  const xs=mirror?-inv:inv;
  for(let i=0;i<N;i++){ const d=sub(pts[i],w); const o=i*3;
    out[o]=dot(d,x)*xs; out[o+1]=dot(d,y)*inv; out[o+2]=dot(d,z)*inv; }
  return out;
}

// Random rotation matrix via QR-ish: build orthonormal frame from random vectors
function randRot(rng){
  const rv=()=>[rng()*2-1,rng()*2-1,rng()*2-1];
  let a=rv(); let la=len(a); a=scl(a,1/la);
  let b=rv(); b=sub(b,scl(a,dot(b,a))); b=scl(b,1/len(b));
  let c=cross(a,b);
  return [a,b,c]; // rows
}
const apply=(R,v)=>[dot(R[0],v),dot(R[1],v),dot(R[2],v)];

// deterministic RNG
let seed=12345; const rng=()=>{seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff;};

// Synthesize a plausible hand: wrist at origin, knuckles spread, fingers out.
function makeHand(){
  const p=new Array(N);
  p[0]=[0,0,0];                      // wrist
  // thumb chain (splayed to the -x side)
  p[1]=[-1.0,1.0,0.3]; p[2]=[-2.2,2.6,0.8]; p[3]=[-3.4,4.4,1.4]; p[4]=[-4.2,5.8,1.9]; p[5]=[-4.8,7.0,2.3];
  // index
  p[6]=[-0.8,1.2,0]; p[7]=[-2.0,8.2,0.2]; p[8]=[-2.3,11.6,0.4]; p[9]=[-2.4,13.8,0.6]; p[10]=[-2.5,15.4,0.7];
  // middle  (knuckle defines the primary axis)
  p[11]=[0,1.2,0]; p[12]=[0,9.0,0]; p[13]=[0,12.6,0]; p[14]=[0,15.0,0]; p[15]=[0,16.8,0];
  // ring
  p[16]=[0.8,1.2,0]; p[17]=[1.9,8.6,-0.2]; p[18]=[2.2,11.9,-0.4]; p[19]=[2.3,14.1,-0.6]; p[20]=[2.4,15.7,-0.7];
  // pinky
  p[21]=[1.5,1.1,0]; p[22]=[3.6,7.6,-0.5]; p[23]=[4.1,10.2,-0.9]; p[24]=[4.3,12.0,-1.2]; p[25]=[4.4,13.2,-1.4];
  return p;
}

const base=makeHand();
const ref=normalize(base);
console.log('ref computed:', ref!==null, 'dim', ref.length);

// Check the two structural invariants documented in the file
const near=(a,b,t=1e-9)=>Math.abs(a-b)<t;
console.log('wrist dims (0,1,2) == 0,0,0 :', near(ref[0],0)&&near(ref[1],0)&&near(ref[2],0));
console.log('middleKnuckle dims (36,37,38) == 0,1,0 :', near(ref[36],0)&&near(ref[37],1)&&near(ref[38],0));

// Rotation + scale + translation invariance over many random transforms
let maxErr=0;
for(let trial=0; trial<2000; trial++){
  const R=randRot(rng);
  const s=0.05+rng()*40;                       // scale 0.05x .. 40x
  const t=[rng()*400-200, rng()*400-200, rng()*400-200];
  const moved=base.map(p=>{ const r=apply(R,p); return [r[0]*s+t[0], r[1]*s+t[1], r[2]*s+t[2]]; });
  const f=normalize(moved);
  if(f===null){ console.log('NULL at trial',trial); break; }
  for(let i=0;i<78;i++) maxErr=Math.max(maxErr, Math.abs(f[i]-ref[i]));
}
console.log('max abs deviation over 2000 random rot+scale+translate:', maxErr.toExponential(3));

// Mirror check: reflecting the hand in x should equal mirror=true on the original
const reflected=base.map(p=>[-p[0],p[1],p[2]]);
const fr=normalize(reflected, false);
const fm=normalize(base, true);
let mErr=0; for(let i=0;i<78;i++) mErr=Math.max(mErr,Math.abs(fr[i]-fm[i]));
console.log('mirror consistency (reflected-hand vs mirror flag):', mErr.toExponential(3));

// Degenerate cases
const collapsed=base.map(()=>[0,0,0]);
console.log('collapsed hand -> null:', normalize(collapsed)===null);
const collinear=base.map((p,i)=>[0,p[1],0]);
console.log('collinear knuckles -> null:', normalize(collinear)===null);
