private withinLetterVariance(list: number[][]): number {
  const n = list ? list.length : 0
  if (n < 2) {
    return 0
  }
  let total = 0
  for (let d = 0; d < FEATURE_DIM; d++) {
    let sum = 0
    for (let s = 0; s < n; s++) {
      sum += list[s][d]
    }
    const mean = sum / n
    let sq = 0
    for (let s = 0; s < n; s++) {
      const e = list[s][d] - mean
      sq += e * e
    }
    total += sq / (n - 1)
  }
  return total / FEATURE_DIM
}

