  try {
    const used = store.getSizeInBytes()
    const max = store.getMaxSizeInBytes()
    if (max > 0) {
      const fraction = used / max
      if (fraction >= 0.8 && !this.storageWarningShown) {
        this.storageWarningShown = true
        print(
