const P=["MOVE between two letters\n(capture mid-transition)","Hand at REST\n(relaxed, by your side)",
"MOVE between two letters\n(different pair)","FLAT PALM\n(fingers together, open)",
"MOVE between two letters\n(capture mid-transition)","POINTING\n(index out, others closed)",
"MOVE between two letters\n(different pair)","LOOSE FIST\n(not a tight S)",
