    this.ls[n] = "current"; this.status = "signing"; this.timer = 0;
  }
  nextFrom(f) { for (let i = f; i < this.phrase.length; i++) if (this.ls[i] === "pending" || this.ls[i] === "current") return i; return -1; }
  remaining(f) { if (f === -1) return 0; let n = 0; for (let i = f; i < this.phrase.length; i++) if (this.ls[i] === "pending" || this.ls[i] === "current") n++; return n; }
  progress() { let t = 0, d = 0; for (const s of this.ls) { if (s === "unsignable") continue; t++; if (s === "done" || s === "skipped") d++; } return t ? d / t : 0; }
  state() {
    return { phrase: this.phrase, index: this.index, current: this.index === -1 ? null : this.phrase[this.index],
      status: this.status, wrongLetter: this.wrong, progress: +this.progress().toFixed(3),
      mistakes: this.mistakes, moc: this.moc, skipped: this.skipped, ls: this.ls.join(",") };
  }
}

