const CONFUSABLE = "ASTMN".split("");
const current = ["HELLO","CLAD","SPECS","SNAP","AR","HELP","NAME","FRIEND","THANK YOU","GOOD MORNING"];
const added = ["LUKE","RIO","CHLOE","PERU"];

function audit(p) {
  const u = p.toUpperCase();
  const doubles = [];
  for (let i = 1; i < u.length; i++) {
    if (u[i] === u[i - 1] && u[i] >= "A" && u[i] <= "Z") doubles.push(u[i] + u[i]);
  }
  const conf = [];
  const seen = {};
  for (const ch of u) {
    if (CONFUSABLE.includes(ch) && !seen[ch]) { seen[ch] = true; conf.push(ch); }
  }
  const jz = [];
  for (const ch of u) if ((ch === "J" || ch === "Z") && !jz.includes(ch)) jz.push(ch);
  const space = u.includes(" ");
  return { doubles, conf, jz, space, clean: doubles.length === 0 && conf.length === 0 && jz.length === 0 };
}

const show = list => {
  for (const p of list) {
    const a = audit(p);
    const flags = [];
    if (a.doubles.length) flags.push("double:" + a.doubles.join("/"));
    if (a.conf.length) flags.push("confusable:" + a.conf.join(""));
    if (a.jz.length) flags.push("MOTION:" + a.jz.join(""));
    if (a.space) flags.push("space");
    console.log("  " + (a.clean ? "CLEAN " : "risk  ") + p.padEnd(14) + (flags.join("  ") || "-"));
  }
};

console.log("CURRENT DEFAULT_PHRASES:");
show(current);
const cleanNow = current.filter(p => audit(p).clean);
console.log("  -> clean: " + cleanNow.length + "/" + current.length + "  " + JSON.stringify(cleanNow));

console.log("");
console.log("PROPOSED ADDITIONS:");
show(added);
console.log("  -> clean: " + added.filter(p => audit(p).clean).length + "/" + added.length);

console.log("");
console.log("TIERING (all 14):");
const all = current.concat(added);
const t1 = all.filter(p => audit(p).clean);
const t2 = all.filter(p => { const a = audit(p); return !a.clean && a.doubles.length + a.conf.length === 1; });
const t3 = all.filter(p => { const a = audit(p); return !a.clean && a.doubles.length + a.conf.length > 1; });
console.log("  tier1 clean          :", JSON.stringify(t1));
console.log("  tier2 one risk factor:", JSON.stringify(t2));
console.log("  tier3 multiple       :", JSON.stringify(t3));
console.log("  total", t1.length + t2.length + t3.length, "of", all.length);

