// Generates SYNTHETIC templates by running plausible hand poses through the
// same normalizeLandmarks math the Lens uses. Not recorded data — a wiring
// fixture so the end-to-end pipeline can be exercised in the Editor.
const fs = require("fs");

const ORDER = ["wrist","thumbToWrist","thumbBaseJoint","thumbKnuckle","thumbMidJoint","thumbTip",
"indexToWrist","indexKnuckle","indexMidJoint","indexUpperJoint","indexTip",
"middleToWrist","middleKnuckle","middleMidJoint","middleUpperJoint","middleTip",
"ringToWrist","ringKnuckle","ringMidJoint","ringUpperJoint","ringTip",
"pinkyToWrist","pinkyKnuckle","pinkyMidJoint","pinkyUpperJoint","pinkyTip"];

const sub=(a,b)=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]];
const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const scl=(a,s)=>[a[0]*s,a[1]*s,a[2]*s];
const len=a=>Math.sqrt(dot(a,a));
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const EPS=1e-4, WRIST=0, IK=7, MK=12, PK=22;

function normalize(pts){
  const w=pts[WRIST], mk=pts[MK], ik=pts[IK], pk=pts[PK];
  const fwd=sub(mk,w); const s=len(fwd); if(s<EPS) return null;
  const inv=1/s, y=scl(fwd,inv);
  const spread=sub(pk,ik);
  const perp=sub(spread, scl(y,dot(spread,y)));
  const pl=len(perp); if(pl<EPS) return null;
  const x=scl(perp,1/pl), z=cross(x,y);
  const out=[];
  for(let i=0;i<26;i++){const d=sub(pts[i],w);
    out.push(+(dot(d,x)*inv).toFixed(4), +(dot(d,y)*inv).toFixed(4), +(dot(d,z)*inv).toFixed(4));}
  return out;
}

// Finger lateral offsets (x) — index leftmost through pinky rightmost on a right hand.
const FX = {index:-2.0, middle:0.0, ring:2.0, pinky:3.7};
const KNUCKLE_Y = {index:8.2, middle:9.0, ring:8.6, pinky:7.6};

// Extended: straight up. Curled: folded toward the palm (+z, lower y).
function fingerJoints(name, extended){
  const x = FX[name], ky = KNUCKLE_Y[name];
  const knuckle = [x, ky, 0];
  if (extended) {
    return [knuckle, [x, ky+3.4, 0.3], [x, ky+5.6, 0.5], [x, ky+7.2, 0.6]];
  }
  return [knuckle, [x, ky+2.2, 1.8], [x, ky+1.4, 3.6], [x, ky-0.6, 4.0]];
}

// Thumb: "out" = extended sideways (L), "up" = alongside index, "across" = tucked over palm.
function thumbJoints(mode){
  if (mode === "out")    return [[-2.2,2.6,0.8], [-4.6,3.6,1.2], [-6.6,4.2,1.6], [-8.2,4.6,1.9]];
  if (mode === "up")     return [[-2.2,2.6,0.8], [-3.4,5.0,1.0], [-4.0,7.4,1.2], [-4.4,9.4,1.4]];
  return                        [[-2.2,2.6,0.8], [-2.0,5.2,2.4], [-0.6,6.6,3.4], [ 0.9,7.2,3.6]]; // across
}

function buildHand(spec){
  const p = new Array(26);
  p[0] = [0,0,0];
  p[1] = [-1.0,1.0,0.3];  // thumbToWrist
  const th = thumbJoints(spec.thumb);
  p[2]=th[0]; p[3]=th[1]; p[4]=th[2]; p[5]=th[3];
  const metas = {index:[-0.8,1.2,0], middle:[0,1.2,0], ring:[0.8,1.2,0], pinky:[1.5,1.1,0]};
  const bases = {index:6, middle:11, ring:16, pinky:21};
  for (const f of ["index","middle","ring","pinky"]) {
    const b = bases[f];
    p[b] = metas[f];
    const j = fingerJoints(f, spec[f]);
    p[b+1]=j[0]; p[b+2]=j[1]; p[b+3]=j[2]; p[b+4]=j[3];
  }
  return p;
}

// ASL handshapes, approximated. Enough to be geometrically distinct.
const LETTERS = {
  L: {thumb:"out",    index:true,  middle:false, ring:false, pinky:false},
  U: {thumb:"across", index:true,  middle:true,  ring:false, pinky:false},
  K: {thumb:"up",     index:true,  middle:true,  ring:false, pinky:false},
  E: {thumb:"across", index:false, middle:false, ring:false, pinky:false},
  C: {thumb:"out",    index:true,  middle:true,  ring:true,  pinky:true },
  H: {thumb:"across", index:true,  middle:true,  ring:false, pinky:false},
  O: {thumb:"across", index:false, middle:false, ring:false, pinky:true },
  P: {thumb:"up",     index:true,  middle:false, ring:false, pinky:true },
  R: {thumb:"across", index:true,  middle:true,  ring:false, pinky:false},
};

let seed = 20260829;
const rnd = () => { seed = (Math.imul(seed,1664525)+1013904223)>>>0; return seed/4294967296; };
const g = () => { let u=rnd()||1e-9, v=rnd(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); };

const SAMPLES = 5, JITTER_CM = 0.22;   // landmark-space jitter, then re-normalize
const letters = {};
for (const [ch, spec] of Object.entries(LETTERS)) {
  const base = buildHand(spec);
  const arr = [];
  for (let s = 0; s < SAMPLES; s++) {
    const jittered = base.map((pt, i) =>
      i === 0 ? pt : pt.map(c => c + (s === 0 ? 0 : g() * JITTER_CM)));
    const norm = normalize(jittered);
    if (!norm) { console.log("degenerate", ch, s); continue; }
    arr.push({ normalized: norm, raw: jittered.flat().map(v => +v.toFixed(4)) });
  }
  letters[ch] = arr;
}

const out = {
  version: 2,
  _comment: "SYNTHETIC WIRING FIXTURE — NOT RECORDED DATA. Generated from approximated ASL hand geometry run through the same normalizeLandmarks math the Lens uses. Exists so the end-to-end pipeline can be exercised in the Editor before a hardware recording session. Replace wholesale with TemplateRecorder output; do not tune thresholds against this.",
  synthetic: true,
  featureDim: 78, rawDim: 78, landmarkCount: 26, rawUnits: "cm_world",
  samplesPerLetter: SAMPLES, signingHand: "right", mirrored: false,
  landmarkOrder: ORDER,
  letters
};

const path = process.argv[2];
fs.writeFileSync(path, JSON.stringify(out, null, 1));

// Separability report: nearest-other-letter vs within-letter spread.
const d=(a,b)=>{let s=0;for(let i=0;i<78;i++){const x=a[i]-b[i];s+=x*x}return Math.sqrt(s)};
const keys=Object.keys(letters);
console.log("letter  within(mean)  nearest-other  ratio");
for(const k of keys){
  const S=letters[k].map(s=>s.normalized);
  let wi=0,wn=0; for(let i=0;i<S.length;i++)for(let j=i+1;j<S.length;j++){wi+=d(S[i],S[j]);wn++}
  const within = wn? wi/wn : 0;
  let best=Infinity,bk="";
  for(const o of keys){ if(o===k) continue;
    for(const a of S) for(const b of letters[o].map(s=>s.normalized)){ const v=d(a,b); if(v<best){best=v;bk=o} } }
  console.log("  "+k+"      "+within.toFixed(3).padStart(8)+"      "+best.toFixed(3).padStart(8)+" ("+bk+")   "+(best/(within||1e-9)).toFixed(1)+"x");
}
console.log("\nwrote "+path+"  letters="+keys.length+" samples="+keys.length*SAMPLES);

