/**
 * SignBridgeScenarios — LEAF coverage for the fingerspelling pipeline.
 *
 * Five scenarios, each isolating one guarantee the pipeline is supposed to
 * make. All of them reset the Lens first, because LEAF runs scenarios
 * sequentially against one live instance and state carries over.
 *
 * Assertions are relative (deltas, unchanged-ness) rather than absolute, for
 * the same reason.
 */

import {Scenario} from "Leaf.lspkg/Scenarios/scenario/Scenario"
import {expect} from "Leaf.lspkg/Utils/common/Expect"
import {frames, getBridge, resetBridge, resolvedCount, waitUntil} from "./SignBridgeLeafSupport"

/** Frames per pose in a script. Comfortably longer than the 18-frame window. */
const HOLD = 30
/** Frames of untracked hand between poses — enough to re-arm unambiguously. */
const GAP = 10

// ---------------------------------------------------------------------------
// 1. A full word completes
// ---------------------------------------------------------------------------

@component
export class SignBridgeCompletesWordScenario extends Scenario {
  async run(): Promise<void> {
    const bridge = getBridge()
    await resetBridge(bridge)

    const target = bridge.getPhraseState().phrase
    expect(target.length).toBeGreaterThan(0)

    // Play the phrase's own letters, in order, with an untracked gap between
    // each so the hold buffer re-arms cleanly.
    const steps = []
    for (let i = 0; i < target.length; i++) {
      const ch = target[i]
      if (ch === " ") {
        continue
      }
      steps.push({letter: ch, frames: HOLD})
      steps.push({letter: null, frames: GAP})
    }

    expect(bridge.playScript(steps)).toBe(true)

    const completed = await waitUntil(() => bridge.getPhraseState().status === "complete", (HOLD + GAP) * 10)

    expect(completed).toBe(true)
    const state = bridge.getPhraseState()
    expect(state.status).toBe("complete")
    expect(state.progress).toBeCloseTo(1, 3)
    expect(state.mistakes).toBe(0)
    expect(state.skipped).toBe(0)

    // The reader-facing string is the whole word.
    expect(bridge.getView().assembled).toBe(target)
  }
}

// ---------------------------------------------------------------------------
// 2. Low-confidence input never commits
// ---------------------------------------------------------------------------

@component
export class SignBridgeLowConfidenceScenario extends Scenario {
  async run(): Promise<void> {
    const bridge = getBridge()
    await resetBridge(bridge)

    const target = bridge.getPhraseState().currentLetter
    expect(target).not.toBe(null)

    // A pose blended halfway between the target and its nearest neighbour sits
    // equidistant from both, so margin confidence collapses toward 0 — the
    // classifier still names a winner, but never a confident one.
    const other = this.nearestOther(bridge, target)
    expect(other).not.toBe(null)

    const before = resolvedCount(bridge)
    expect(bridge.playScript([{letter: target, blendWith: other, blend: 0.5, frames: HOLD * 6}])).toBe(true)

    // Hold it far longer than the window would need for a clean commit.
    await frames(HOLD * 5)

    const state = bridge.getPhraseState()
    const hold = bridge.getHoldState()

    // Nothing advanced, nothing was marked wrong — it simply never committed.
    expect(resolvedCount(bridge)).toBe(before)
    expect(state.currentLetter).toBe(target)
    expect(state.mistakes).toBe(0)
    expect(state.status).not.toBe("complete")

    // The bar reflects the stall rather than sitting at zero or full.
    expect(hold.meanConfidence).toBeLessThan(0.3)
    expect(hold.progress).toBeLessThan(1)
  }

  /** Closest other loaded letter, by first-template distance. */
  private nearestOther(bridge: ReturnType<typeof getBridge>, letter: string): string | null {
    const view = bridge.getPhraseState()
    let best: string | null = null
    let bestDistance = Infinity
    const letters = bridge.getLoadedLetters()
    for (let i = 0; i < letters.length; i++) {
      if (letters[i] === letter) {
        continue
      }
      const d = bridge.distanceBetween(letter, letters[i])
      if (d < bestDistance) {
        bestDistance = d
        best = letters[i]
      }
    }
    return best
  }
}

// ---------------------------------------------------------------------------
// 3. A hold interrupted midway does not commit
// ---------------------------------------------------------------------------

@component
export class SignBridgeInterruptedHoldScenario extends Scenario {
  async run(): Promise<void> {
    const bridge = getBridge()
    await resetBridge(bridge)

    const target = bridge.getPhraseState().currentLetter
    const before = resolvedCount(bridge)
    const windowFrames = bridge.getHoldState().capacity

    // Hold the right letter for well under the window, then lose the hand.
    // Losing tracking is unambiguous evidence the pose ended, so the window is
    // wiped rather than merely diluted.
    const partial = Math.floor(windowFrames / 2)
    expect(partial).toBeGreaterThan(1)

    expect(
      bridge.playScript([
        {letter: target, frames: partial},
        {letter: null, frames: HOLD * 2}
      ])
    ).toBe(true)

    // Let the partial hold accumulate.
    await frames(partial)
    const midway = bridge.getHoldState()
    expect(midway.filled).toBeLessThan(midway.capacity)

    // Now ride out the untracked stretch.
    await frames(HOLD)

    const hold = bridge.getHoldState()
    expect(resolvedCount(bridge)).toBe(before)
    expect(bridge.getPhraseState().currentLetter).toBe(target)
    // Untracked hard-resets: empty window, re-armed, no candidate.
    expect(hold.filled).toBe(0)
    expect(hold.armed).toBe(true)
    expect(hold.candidate).toBeNull()
    expect(hold.progress).toBe(0)
  }
}

// ---------------------------------------------------------------------------
// 4. A wrong letter does not advance the index
// ---------------------------------------------------------------------------

@component
export class SignBridgeWrongLetterScenario extends Scenario {
  async run(): Promise<void> {
    const bridge = getBridge()
    await resetBridge(bridge)

    const before = bridge.getPhraseState()
    const target = before.currentLetter
    const wrong = this.aDifferentLetter(bridge, target)
    expect(wrong).not.toBe(null)

    expect(bridge.playScript([{letter: wrong, frames: HOLD * 4}])).toBe(true)

    const flagged = await waitUntil(() => bridge.getPhraseState().mistakes > before.mistakes, HOLD * 4)
    expect(flagged).toBe(true)

    const after = bridge.getPhraseState()

    // The mistake is recorded and visible...
    expect(after.mistakes).toBe(before.mistakes + 1)
    expect(after.status).toBe("wrong")
    expect(after.wrongLetter).toBe(wrong)

    // ...but the index does not move, the phrase is not reset, and the same
    // letter is still expected.
    expect(after.index).toBe(before.index)
    expect(after.currentLetter).toBe(target)
    expect(resolvedCount(bridge)).toBe(resolvedCount(bridge))
    expect(after.progress).toBeCloseTo(before.progress, 3)

    // Both panels surface it — the view is what they render from.
    const view = bridge.getView()
    expect(view.wrongSigned).toBe(wrong)
    expect(view.wrongExpected).toBe(target)
  }

  private aDifferentLetter(bridge: ReturnType<typeof getBridge>, letter: string): string | null {
    const letters = bridge.getLoadedLetters()
    for (let i = 0; i < letters.length; i++) {
      if (letters[i] !== letter) {
        return letters[i]
      }
    }
    return null
  }
}

// ---------------------------------------------------------------------------
// 5. A single rejected frame must NOT re-arm into a spurious double
// ---------------------------------------------------------------------------

@component
export class SignBridgeNoSpuriousDoubleScenario extends Scenario {
  async run(): Promise<void> {
    const bridge = getBridge()
    await resetBridge(bridge)

    const target = bridge.getPhraseState().currentLetter

    // The distance gate is off by default, so no frame can ever be rejected.
    // Set it just below the nearest-neighbour distance: real poses pass, the
    // scaled-away "far" pose does not.
    const nearest = bridge.nearestOtherDistance(target)
    expect(nearest).toBeGreaterThan(0)
    bridge.setMaxDistance(nearest * 0.5)

    const rearm = bridge.getHoldState().nonMatchingRun
    expect(rearm).toBe(0)

    // Commit the letter, keep holding it, drop in ONE rejected frame, then
    // keep holding. A one-frame dropout must not look like a deliberate bounce.
    expect(
      bridge.playScript([
        {letter: target, frames: HOLD},
        {letter: target, farScale: 4, frames: 1},
        {letter: target, frames: HOLD * 3}
      ])
    ).toBe(true)

    const committed = await waitUntil(() => resolvedCount(bridge) > 0, HOLD * 3)
    expect(committed).toBe(true)

    const afterFirst = resolvedCount(bridge)
    expect(afterFirst).toBe(1)

    // Ride out the glitch and the long hold that follows it.
    await frames(HOLD * 3)

    // Exactly one commit — the glitch did not manufacture a second.
    expect(resolvedCount(bridge)).toBe(afterFirst)
    expect(bridge.getPhraseState().mistakes).toBe(0)

    // Restore the default so later scenarios are unaffected.
    bridge.setMaxDistance(0)
  }
}

