/** Distance from a letter's first template to its nearest other letter. */
nearestOtherDistance(letter: string): number {
  const a = this.poseFor(letter)
  if (a === null) {
    return Infinity
  }
  let best = Infinity
  const letters = this.classifier.loadedLetters()
  for (let i = 0; i < letters.length; i++) {
    if (letters[i] === letter) {
      continue
    }
    const b = this.poseFor(letters[i])
    if (b === null) {
      continue
    }
    let sum = 0
    for (let d = 0; d < a.length; d++) {
      const diff = a[d] - b[d]
      sum += diff * diff
    }
    const dist = Math.sqrt(sum)
    if (dist < best) {
      best = dist
    }
  }
  return best
}

