const pluginSystemInterface = pluginSystem as any;
let found = false;
let ids: string[] = [];
try {
  const all = pluginSystemInterface.plugins || [];
  for (const p of all) {
    const id = p && p.id ? String(p.id) : String(p);
    ids.push(id);
    if (id.indexOf("LeafPlugin") !== -1 || id.indexOf("com.snap.leaf") !== -1) { found = true; }
  }
} catch (e) {
  return {error: String(e)};
}
return {leafPluginFound: found, matching: ids.filter(i => i.toLowerCase().indexOf("leaf") !== -1), total: ids.length};
